package com.claudesidebar;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Talks to the companion script through files in the plugin's data directory. The plugin itself
 * never opens a connection or starts a program: it writes a request file, and the companion, which
 * the user runs separately, answers by appending events to a reply file.
 *
 * <pre>
 * companion.json        rewritten by the companion every few seconds while it is running
 * plugin.json           rewritten by the plugin every few seconds while it is running, so the
 *                       companion can stop when RuneLite closes
 * requests/ID.json      a prompt, written by the plugin and removed by the companion
 * requests/ID.cancel    asks the companion to stop answering ID
 * replies/ID.jsonl      one event per line, appended by the companion
 * </pre>
 */
@Slf4j
class FileBridgeBackend implements ChatBackend
{
	private static final long POLL_MILLIS = 150;
	private static final long HEARTBEAT_STALE_MILLIS = 10_000;
	private static final long PLUGIN_HEARTBEAT_SECONDS = 5;

	private static final String NOT_RUNNING = "The companion is not running. Start it with "
		+ "start-companion.cmd from the companion folder, then send again. "
		+ "Setup help: github.com/AnBaget/claude-sidebar";

	private final Filepath directory;
	private final ScheduledExecutorService executor;
	private final Gson gson;

	// Claude session to continue, as reported by the companion. Null starts a new conversation.
	private String session;
	private Exchange active;
	private ScheduledFuture<?> heartbeat;

	FileBridgeBackend(Filepath directory, ScheduledExecutorService executor, Gson gson)
	{
		this.directory = directory;
		this.executor = executor;
		this.gson = gson;
	}

	synchronized void start()
	{
		heartbeat = executor.scheduleAtFixedRate(this::writeHeartbeat, 0, PLUGIN_HEARTBEAT_SECONDS, TimeUnit.SECONDS);
	}

	private void writeHeartbeat()
	{
		try
		{
			directory.createDirectories();
			directory.join("plugin.json").write("{\"time\":" + System.currentTimeMillis() + "}");
		}
		catch (IOException e)
		{
			log.debug("could not write plugin heartbeat", e);
		}
	}

	@Override
	public synchronized void send(String prompt, ChatListener listener)
	{
		stop(active);

		Exchange exchange = new Exchange(UUID.randomUUID().toString(), listener);
		active = exchange;

		Request request = new Request();
		request.id = exchange.id;
		request.time = System.currentTimeMillis();
		request.session = session;
		request.prompt = prompt;

		executor.execute(() -> begin(exchange, request));
	}

	@Override
	public synchronized void cancel()
	{
		stop(active);
		active = null;
	}

	@Override
	public synchronized void newConversation()
	{
		session = null;
	}

	@Override
	public void shutDown()
	{
		cancel();

		synchronized (this)
		{
			if (heartbeat != null)
			{
				heartbeat.cancel(false);
				heartbeat = null;
			}
		}

		// Removing the heartbeat lets the companion stop straight away instead of waiting for it to go stale.
		executor.execute(() ->
		{
			try
			{
				directory.join("plugin.json").deleteIfExists();
			}
			catch (IOException e)
			{
				log.debug("could not delete plugin heartbeat", e);
			}
		});
	}

	private void begin(Exchange exchange, Request request)
	{
		if (!isActive(exchange))
		{
			return;
		}

		try
		{
			if (!companionAlive())
			{
				fail(exchange, NOT_RUNNING);
				return;
			}

			Filepath requests = directory.join("requests");
			requests.createDirectories();

			// Written under another name and moved into place, so the companion never reads half a file.
			Filepath partial = requests.join(exchange.id + ".part");
			partial.write(gson.toJson(request));
			partial.moveTo(requests.join(exchange.id + ".json"), StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException e)
		{
			log.debug("could not write request", e);
			fail(exchange, "Could not write the request file: " + e.getMessage());
			return;
		}

		synchronized (this)
		{
			if (active == exchange)
			{
				exchange.poll = executor.scheduleWithFixedDelay(() -> poll(exchange), POLL_MILLIS, POLL_MILLIS, TimeUnit.MILLISECONDS);
			}
		}
	}

	private void poll(Exchange exchange)
	{
		if (!isActive(exchange))
		{
			return;
		}

		try
		{
			for (String line : readNewLines(exchange))
			{
				if (!handle(exchange, line))
				{
					return;
				}
			}

			if (!companionAlive())
			{
				fail(exchange, "The companion stopped responding. Restart it and send again.");
			}
		}
		catch (IOException e)
		{
			log.debug("could not read reply", e);
			fail(exchange, "Could not read the reply file: " + e.getMessage());
		}
	}

	/**
	 * @return false once the exchange is over
	 */
	private boolean handle(Exchange exchange, String line)
	{
		Event event;
		try
		{
			event = gson.fromJson(line, Event.class);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("ignoring malformed reply line: {}", line);
			return true;
		}

		if (event == null || event.type == null)
		{
			return true;
		}

		switch (event.type)
		{
			case "text":
				if (event.text != null)
				{
					exchange.listener.onText(event.text);
				}
				return true;
			case "activity":
				if (event.text != null)
				{
					exchange.listener.onActivity(event.text);
				}
				return true;
			case "done":
				if (finish(exchange))
				{
					synchronized (this)
					{
						session = event.session;
					}
					exchange.listener.onDone();
				}
				return false;
			case "error":
				fail(exchange, event.text != null ? event.text : "The companion reported an error.");
				return false;
			default:
				return true;
		}
	}

	private String[] readNewLines(Exchange exchange) throws IOException
	{
		Filepath reply = replyFile(exchange);
		if (!reply.exists())
		{
			return new String[0];
		}

		byte[] bytes;
		try (FileChannel channel = reply.openFileChannel(StandardOpenOption.READ))
		{
			long remaining = channel.size() - exchange.offset;
			if (remaining <= 0)
			{
				return new String[0];
			}

			ByteBuffer buffer = ByteBuffer.allocate((int) Math.min(remaining, 1 << 20));
			channel.position(exchange.offset);
			while (buffer.hasRemaining() && channel.read(buffer) > 0)
			{
				// keep reading until the buffer is full or the file ends
			}
			bytes = new byte[buffer.position()];
			buffer.flip();
			buffer.get(bytes);
		}

		// The companion may be part way through a line. Only take whole lines and leave the rest for the next poll.
		int end = bytes.length;
		while (end > 0 && bytes[end - 1] != '\n')
		{
			end--;
		}
		if (end == 0)
		{
			return new String[0];
		}

		exchange.offset += end;
		return new String(bytes, 0, end - 1, StandardCharsets.UTF_8).split("\n");
	}

	private boolean companionAlive() throws IOException
	{
		Filepath heartbeat = directory.join("companion.json");
		return heartbeat.exists()
			&& System.currentTimeMillis() - heartbeat.getLastModifiedTime().toMillis() < HEARTBEAT_STALE_MILLIS;
	}

	private void fail(Exchange exchange, String message)
	{
		if (finish(exchange))
		{
			exchange.listener.onError(message);
		}
	}

	/**
	 * Ends an exchange that ran to completion.
	 *
	 * @return false if it had already been cancelled or replaced, in which case its listener must stay silent
	 */
	private boolean finish(Exchange exchange)
	{
		synchronized (this)
		{
			if (active != exchange)
			{
				return false;
			}

			active = null;
			if (exchange.poll != null)
			{
				exchange.poll.cancel(false);
			}
		}

		try
		{
			replyFile(exchange).deleteIfExists();
		}
		catch (IOException e)
		{
			log.debug("could not delete reply file", e);
		}
		return true;
	}

	/**
	 * Abandons an exchange and tells the companion to stop working on it. Caller holds the lock.
	 */
	private void stop(Exchange exchange)
	{
		if (exchange == null)
		{
			return;
		}

		if (exchange.poll != null)
		{
			exchange.poll.cancel(false);
		}

		executor.execute(() ->
		{
			try
			{
				Filepath requests = directory.join("requests");
				requests.createDirectories();
				requests.join(exchange.id + ".cancel").write("");
			}
			catch (IOException e)
			{
				log.debug("could not write cancel file", e);
			}
		});
	}

	private synchronized boolean isActive(Exchange exchange)
	{
		return active == exchange;
	}

	private Filepath replyFile(Exchange exchange)
	{
		return directory.join("replies", exchange.id + ".jsonl");
	}

	private static class Exchange
	{
		private final String id;
		private final ChatListener listener;

		// Only touched from the executor.
		private long offset;

		// Guarded by the backend's lock.
		private ScheduledFuture<?> poll;

		private Exchange(String id, ChatListener listener)
		{
			this.id = id;
			this.listener = listener;
		}
	}

	private static class Request
	{
		String id;
		long time;
		String session;
		String prompt;
	}

	private static class Event
	{
		String type;
		String text;
		String session;
	}
}

package com.claudesidebar;

interface ChatListener
{
	/**
	 * More text of the reply has arrived.
	 */
	void onText(String delta);

	/**
	 * What Claude is doing while no text is arriving, such as the tool it is using.
	 */
	void onActivity(String description);

	void onDone();

	void onError(String message);
}

package com.claudesidebar;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.event.ActionEvent;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import javax.swing.AbstractAction;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.KeyStroke;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.text.DefaultEditorKit;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class ClaudeSidebarPanel extends PluginPanel
{
	private static final Color CLAUDE_COLOR = new Color(0xD9, 0x77, 0x57);
	private static final int MAX_MESSAGES = 200;
	private static final String IDLE_STATUS = "Enter sends, Shift+Enter adds a line";

	private final ChatBackend backend;

	private final JPanel messages = new JPanel();
	private final JScrollPane transcriptScroll;
	private final JTextArea input = new JTextArea(4, 0);
	private final JButton sendButton = new JButton("Send");
	private final JLabel status = new JLabel(IDLE_STATUS);

	// The reply being streamed. Callbacks from an older reply compare against this and drop out.
	private Object activeReply;
	private JTextArea replyText;

	ClaudeSidebarPanel(ChatBackend backend)
	{
		super(false);
		this.backend = backend;

		setLayout(new BorderLayout(0, 6));
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		messages.setLayout(new BoxLayout(messages, BoxLayout.Y_AXIS));
		messages.setBackground(ColorScheme.DARK_GRAY_COLOR);

		TranscriptPanel transcript = new TranscriptPanel();
		transcript.add(messages, BorderLayout.NORTH);

		transcriptScroll = new JScrollPane(transcript,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		transcriptScroll.setBorder(null);
		transcriptScroll.getVerticalScrollBar().setUnitIncrement(16);

		add(buildHeader(), BorderLayout.NORTH);
		add(transcriptScroll, BorderLayout.CENTER);
		add(buildComposer(), BorderLayout.SOUTH);
	}

	private JPanel buildHeader()
	{
		JLabel title = new JLabel("Claude");
		title.setForeground(CLAUDE_COLOR);
		title.setFont(FontManager.getRunescapeBoldFont());

		JButton newChat = new JButton("New chat");
		newChat.setFocusable(false);
		newChat.setToolTipText("Forget this conversation and start a fresh one");
		newChat.addActionListener(e -> newChat());

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.add(title, BorderLayout.WEST);
		header.add(newChat, BorderLayout.EAST);
		return header;
	}

	private JPanel buildComposer()
	{
		input.setLineWrap(true);
		input.setWrapStyleWord(true);
		input.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		input.setForeground(ColorScheme.TEXT_COLOR);
		input.setCaretColor(ColorScheme.TEXT_COLOR);
		input.setBorder(new EmptyBorder(4, 6, 4, 6));

		input.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "send");
		input.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, InputEvent.SHIFT_DOWN_MASK),
			DefaultEditorKit.insertBreakAction);
		input.getActionMap().put("send", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				send();
			}
		});

		JScrollPane inputScroll = new JScrollPane(input,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		inputScroll.setBorder(null);

		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setHorizontalAlignment(SwingConstants.LEFT);

		sendButton.setFocusable(false);
		sendButton.addActionListener(e ->
		{
			if (activeReply != null)
			{
				stop();
			}
			else
			{
				send();
			}
		});

		JPanel composer = new JPanel(new BorderLayout(0, 4));
		composer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		composer.add(status, BorderLayout.NORTH);
		composer.add(inputScroll, BorderLayout.CENTER);
		composer.add(sendButton, BorderLayout.SOUTH);
		return composer;
	}

	private void send()
	{
		String prompt = input.getText().trim();
		if (prompt.isEmpty() || activeReply != null)
		{
			return;
		}

		input.setText("");
		addMessage("You", ColorScheme.LIGHT_GRAY_COLOR, prompt);
		replyText = addMessage("Claude", CLAUDE_COLOR, "");

		Object reply = new Object();
		activeReply = reply;
		sendButton.setText("Stop");
		status.setText("Thinking...");

		backend.send(prompt, new ChatListener()
		{
			@Override
			public void onText(String delta)
			{
				SwingUtilities.invokeLater(() ->
				{
					if (activeReply == reply)
					{
						appendReply(delta);
					}
				});
			}

			@Override
			public void onActivity(String description)
			{
				SwingUtilities.invokeLater(() ->
				{
					if (activeReply == reply)
					{
						status.setText(description);
					}
				});
			}

			@Override
			public void onDone()
			{
				SwingUtilities.invokeLater(() ->
				{
					if (activeReply == reply)
					{
						finishReply();
					}
				});
			}

			@Override
			public void onError(String message)
			{
				SwingUtilities.invokeLater(() ->
				{
					if (activeReply == reply)
					{
						finishReply();
						addMessage("Error", ColorScheme.PROGRESS_ERROR_COLOR, message);
					}
				});
			}
		});
	}

	private void stop()
	{
		backend.cancel();
		finishReply();
	}

	private void newChat()
	{
		backend.cancel();
		backend.newConversation();
		finishReply();
		messages.removeAll();
		messages.revalidate();
		messages.repaint();
		input.requestFocusInWindow();
	}

	private void appendReply(String delta)
	{
		boolean follow = isScrolledToEnd();
		replyText.append(delta);
		if (follow)
		{
			scrollToEnd();
		}
	}

	private void finishReply()
	{
		if (replyText != null && replyText.getText().isEmpty())
		{
			messages.remove(replyText.getParent());
			messages.revalidate();
			messages.repaint();
		}

		activeReply = null;
		replyText = null;
		sendButton.setText("Send");
		status.setText(IDLE_STATUS);
	}

	private JTextArea addMessage(String author, Color authorColor, String text)
	{
		JLabel name = new JLabel(author);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(authorColor);

		JTextArea body = new JTextArea(text);
		body.setEditable(false);
		body.setLineWrap(true);
		body.setWrapStyleWord(true);
		body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.setForeground(ColorScheme.TEXT_COLOR);
		body.setBorder(new EmptyBorder(4, 6, 4, 6));

		JPanel message = new JPanel(new BorderLayout(0, 2));
		message.setBackground(ColorScheme.DARK_GRAY_COLOR);
		message.setBorder(new EmptyBorder(0, 0, 8, 0));
		message.add(name, BorderLayout.NORTH);
		message.add(body, BorderLayout.CENTER);

		messages.add(message);
		while (messages.getComponentCount() > MAX_MESSAGES)
		{
			messages.remove(0);
		}

		messages.revalidate();
		scrollToEnd();
		return body;
	}

	private boolean isScrolledToEnd()
	{
		JScrollBar bar = transcriptScroll.getVerticalScrollBar();
		return bar.getValue() + bar.getVisibleAmount() >= bar.getMaximum() - 16;
	}

	private void scrollToEnd()
	{
		// Queued so it runs after the layout pass that makes room for the new text.
		SwingUtilities.invokeLater(() ->
		{
			JScrollBar bar = transcriptScroll.getVerticalScrollBar();
			bar.setValue(bar.getMaximum());
		});
	}

	/**
	 * Holds the transcript at the width of the scroll pane, so messages wrap instead of scrolling sideways.
	 */
	private static class TranscriptPanel extends JPanel implements Scrollable
	{
		private TranscriptPanel()
		{
			super(new BorderLayout());
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.claudesidebar;

import com.google.gson.Gson;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
	name = "Claude Sidebar",
	description = "Chat with Claude from a side panel, without the chatbox character limit",
	tags = {"claude", "ai", "assistant", "chat", "panel"},
	internalName = "claude-sidebar"
)
public class ClaudeSidebarPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private ChatBackend backend;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		FileBridgeBackend bridge = new FileBridgeBackend(getPluginDirectory(), executor, gson);
		bridge.start();
		backend = bridge;

		navButton = NavigationButton.builder()
			.tooltip("Claude")
			.icon(buildIcon())
			.priority(10)
			.panel(new ClaudeSidebarPanel(backend))
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		backend.shutDown();
		navButton = null;
		backend = null;
	}

	private static BufferedImage buildIcon()
	{
		final int size = 18;
		final int centre = size / 2;
		final int rays = 4;

		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(0xD9, 0x77, 0x57));
		graphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < rays; i++)
		{
			double angle = Math.PI * i / rays;
			int dx = (int) Math.round(Math.cos(angle) * (centre - 2));
			int dy = (int) Math.round(Math.sin(angle) * (centre - 2));
			graphics.drawLine(centre - dx, centre - dy, centre + dx, centre + dy);
		}
		graphics.dispose();
		return image;
	}
}

package com.claudesidebar;

/**
 * Something that can answer a prompt. Implementations must not block the caller and may
 * invoke the listener from any thread.
 */
interface ChatBackend
{
	void send(String prompt, ChatListener listener);

	/**
	 * Stops the reply in progress, if any. The listener of the stopped reply is not called again.
	 */
	void cancel();

	/**
	 * Forgets the conversation so the next prompt starts a fresh one.
	 */
	void newConversation();

	void shutDown();
}
